(() => {
  'use strict';

  const options = Joomla.getOptions('plg_system_iceesportsteamlinks', {});
  const map = options.map || {};
  const ROOT = '[id^="esp-widget-"]';
  const STANDINGS = '#esp-widget-standings-new';
  const CELL = 'td[type="team"].esp-w-st-new__td';
  const LOGO = '.esp-w-st-new__team-logo';
  const LINK = 'a.ice-esports-team-link[data-ice-standings-overlay="1"]';
  const observed = new WeakSet();
  const log = (...args) => {
    if (options.debug === true) console.debug('ICE eSports Team Links:', ...args);
  };
  const id = (value) => /^\d+$/.test(String(value || '')) && Number.isSafeInteger(Number(value)) && Number(value) > 0
    ? String(Number(value)) : '';
  const set = (element, name, value) => {
    if (element.getAttribute(name) !== value) element.setAttribute(name, value);
  };

  const urlFor = (teamId) => {
    if (!teamId || !Object.prototype.hasOwnProperty.call(map, teamId)) return '';
    const raw = map[teamId];
    if (typeof raw !== 'string' || !raw.startsWith('/') || raw.startsWith('//')) return '';
    try {
      const url = new URL(raw, window.location.href);
      if (url.origin !== window.location.origin
        || /\/component\/content(?:\/|$)/i.test(decodeURIComponent(url.pathname))
        || [...url.searchParams.keys()].some(key => key.toLowerCase() === 'teamid')) return '';
      return raw;
    } catch (_) {
      return '';
    }
  };

  const anchorInfo = (anchor) => {
    try {
      const url = new URL(anchor.getAttribute('href') || '', window.location.href);
      let teamId = '';
      let otherDetail = false;
      for (const [key, value] of url.searchParams) {
        if (key.toLowerCase() === 'teamid') teamId = id(value);
        if (/^(playerid|gameid|matchid)$/i.test(key)) otherDetail = true;
      }
      // Retain identity after a module rewrites href. An older module's content
      // fallback must never overwrite a valid menu URL from this resolver.
      teamId = teamId || id(anchor.dataset.iceResolvedTeamId || anchor.dataset.iceUnresolvedTeamId);
      return {teamId, otherDetail};
    } catch (_) {
      return {teamId:'', otherDetail:false};
    }
  };

  const rewriteAnchor = (anchor) => {
    if (!(anchor instanceof HTMLAnchorElement) || anchor.matches(LINK)) return;
    const {teamId, otherDetail} = anchorInfo(anchor);
    if (!teamId || otherDetail) return;
    const url = urlFor(teamId);
    if (url) {
      set(anchor, 'href', url);
      anchor.removeAttribute('aria-disabled');
      if (anchor.dataset.iceTeamlinksTabindexRemoved === '1') {
        anchor.removeAttribute('tabindex');
        delete anchor.dataset.iceTeamlinksTabindexRemoved;
      }
      delete anchor.dataset.iceUnresolvedTeamId;
      anchor.dataset.iceResolvedTeamId = teamId;
    } else {
      anchor.removeAttribute('href');
      anchor.removeAttribute('target');
      set(anchor, 'aria-disabled', 'true');
      if (!anchor.hasAttribute('tabindex')) {
        set(anchor, 'tabindex', '-1');
        anchor.dataset.iceTeamlinksTabindexRemoved = '1';
      }
      anchor.dataset.iceUnresolvedTeamId = teamId;
      delete anchor.dataset.iceResolvedTeamId;
    }
  };

  const teamIdFor = (cell) => {
    const src = cell.querySelector(LOGO)?.getAttribute('src') || '';
    const match = src.match(/\/img\/logos\/(\d+)\.png(?:[?#].*)?$/i);
    return match ? id(match[1]) : '';
  };
  const teamLabel = (cell) => cell.querySelector('.esp-w-st-new__team-name[type="fullName"]')?.textContent.trim()
    || cell.querySelector('.esp-w-st-new__team-name')?.textContent.trim()
    || cell.querySelector(LOGO)?.getAttribute('alt')?.trim() || 'Team';

  const ensureLink = (cell) => {
    // The provider changes the td background on hover. Preserve its normal
    // theme/sort appearance using computed styles, without generated classes.
    let sample = cell;
    if (cell.matches(':hover')) {
      sample = cell.style.getPropertyValue('--ice-teamlink-background') ? null
        : [...cell.closest(STANDINGS).querySelectorAll(CELL)].find(other => !other.matches(':hover'));
    }
    if (sample) {
      const style = getComputedStyle(sample);
      cell.style.setProperty('--ice-teamlink-background', style.backgroundColor);
      cell.style.setProperty('--ice-teamlink-color', style.color);
    }
    const teamId = teamIdFor(cell);
    const url = urlFor(teamId);
    let link = cell.querySelector(':scope > ' + LINK);
    if (!url) {
      link?.remove();
      cell.classList.remove('ice-esports-team-cell-linked');
      cell.dataset.iceUnresolvedTeamId = teamId || 'unknown';
      return null;
    }
    delete cell.dataset.iceUnresolvedTeamId;
    // Keep React's children untouched. An empty sibling with an accessible name
    // avoids reparenting and never nests an interactive element.
    if (cell.querySelector('a:not(' + LINK + '), button, input, select, textarea, [contenteditable="true"], [role="button"]')) {
      link?.remove();
      cell.classList.remove('ice-esports-team-cell-linked');
      return null;
    }
    if (!link) {
      link = document.createElement('a');
      link.className = 'ice-esports-team-link';
      link.dataset.iceStandingsOverlay = '1';
      cell.appendChild(link);
    }
    set(link, 'href', url);
    set(link, 'aria-label', teamLabel(cell));
    link.dataset.iceResolvedTeamId = teamId;
    cell.classList.add('ice-esports-team-cell-linked');
    return link;
  };

  const scan = (root) => {
    root.querySelectorAll('a').forEach(rewriteAnchor);
    if (root.matches(STANDINGS)) root.querySelectorAll(CELL).forEach(ensureLink);
  };

  const observe = (root) => {
    if (observed.has(root)) return;
    observed.add(root);
    scan(root);
    let queued = false;
    new MutationObserver(() => {
      if (queued) return;
      queued = true;
      queueMicrotask(() => {
        queued = false;
        if (root.isConnected) scan(root);
      });
    }).observe(root, {
      childList:true, subtree:true, attributes:true,
      attributeFilter:['href', 'src', 'alt']
    });
  };

  // Observed in Chrome DevTools: React's td onClick runs at the widget root in
  // bubble phase and writes window.location.href. Window capture precedes both
  // React root phases even if this script loads after the provider.
  const guard = (event) => {
    const target = event.target instanceof Element ? event.target : event.target?.parentElement;
    if (!target) return;
    const cell = target.closest(CELL);
    if (cell?.closest(STANDINGS)) {
      const url = urlFor(teamIdFor(cell));
      const link = ensureLink(cell);
      event.stopImmediatePropagation();
      if (url && link && target.closest(LINK) === link) {
        // Native defaults preserve Enter, Ctrl/Cmd-click and middle-click.
        // Do not preventDefault: only the provider's event path is suppressed.
        return;
      }
      const control = target.closest('a[href], button, input, select, textarea, [role="button"]');
      if (url && control instanceof HTMLAnchorElement && control.getAttribute('href') === url) return;
      event.preventDefault();
      if (!url || control) return; // Standings always fails closed for unknown IDs.
      // Safety net during a synchronous React commit, before MutationObserver
      // restores the anchor. The ordinary case uses the real href above.
      if (event.type === 'auxclick' && event.button !== 1) return;
      if (event.button === 1 || event.ctrlKey || event.metaKey || event.shiftKey) {
        window.open(url, '_blank', 'noopener');
      } else if (event.type === 'click' && event.button === 0) {
        window.location.assign(url);
      }
      return;
    }

    const anchor = target.closest('a');
    if (!anchor?.closest(ROOT)) return;
    const info = anchorInfo(anchor);
    if (!info.teamId || info.otherDetail) return;
    rewriteAnchor(anchor);
    if (urlFor(info.teamId)) event.stopImmediatePropagation();
    else {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  };
  window.addEventListener('click', guard, true);
  window.addEventListener('auxclick', guard, true);

  const start = () => {
    document.querySelectorAll(ROOT).forEach(observe);
    new MutationObserver(mutations => {
      for (const mutation of mutations) for (const node of mutation.addedNodes) {
        if (!(node instanceof Element)) continue;
        if (node.matches(ROOT)) observe(node);
        node.querySelectorAll(ROOT).forEach(observe);
      }
    }).observe(document.body, {childList:true, subtree:true});
    log('mappedTeams=' + Object.keys(map).length);
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, {once:true});
  else start();
})();
